\begin{align}\label{def-DF}
D_F: = D_F(W, b) = \left\{
\begin{array}{lc}
\displaystyle 1 - \frac{\log \mathbb{E}[W^2]}{\log b} & \quad \text{if $\mathbb{E} [ W^{(2)}\log W^{(2)}] \le \log b$}
\\
\displaystyle 1 -   \inf_{1/2\le t\le 1} \frac{\log  \mathbb{E}[b^{1-t}W^{2t}]}{ t \log b} & \quad \text{if $\mathbb{E} [ W^{(2)}\log W^{(2)}] >\log b$}
\end{array}
\right. .
\end{align}

we say that the random weight $W$ is in: 
\begin{itemize}
\item {\it squared sub-critical regime}  if $\mathbb{E}[W^{(2)}\log W^{(2)}]< \log b$; 
\item {\it squared critical regime} if $\mathbb{E}[W^{(2)}\log W^{(2)}] =  \log b$;  
\item {\it squared super-critical regime} if $\mathbb{E}[W^{(2)}\log W^{(2)}]>\log b$.

\label{rem-non-lattice}
The non-lattice assumption  on $\log W$  is needed only in the upper bound of $\dim_F(\mu_\infty)$ when $W$ is  in the squared super-critical regime.  In the sequel to this paper,  we will obtain the same upper bound of $\dim_F(\mu_\infty)$ without the non-lattice assumption on $\log W$   by establishing explicitly  the optimal  exponent  $\alpha$ of the  H\"older regularity: 
\begin{align}\label{Hol-optimal}
\mu_\infty([x,y]) = O (|x-y|^{\alpha})  \quad \text{for all  $0\le x<y \le 1$.} 
\end{align}
 See  Corollary \ref{cor-holder} below and its proof in \S \ref{sec-cor-holder} for more details.

\label{cor-salem}
Assume that $\mathbb{E}[W\log W]<\log b$ and $\mathbb{E}[W^t]<\infty$ for all $t>0$.  Then almost surely on $\{\mu_\infty\ne 0\}$,   $\mu_\infty$ is Salem if and only if $W$ has a two-point distribution : 
\begin{align}\label{2-pt-w}
\mathbb{P}(W= x^{-1})= 1 - \mathbb{P}(W=0) = x \quad \text{\,with\,} \quad  b^{-1}<x\le 1.
\end{align}

\label{cor-log-normal}
For the   log-normal random weights $W=e^{\sigma N-\sigma^2/2}$ with $0< \sigma < \sqrt{2 \log b}$,  we have 
 \[
 \dim_F(\mu_\infty)  =  \left\{
 \begin{array}{ll}
  \displaystyle 1-  \sigma^2/\log b  & \text{if $ \displaystyle \frac{\sigma^2}{\log b} \le  \frac{1}{2}$}
  \\  
    \displaystyle     1-  \sigma^2/\log b  +     \big( 1 -  \sigma \sqrt{2/\log b} \big)^2 & \text{if $ \displaystyle \frac{1}{2} <   \frac{\sigma^2}{\log b} <  2$}
 \end{array}
 \right.. 
 \]

\begin{align}\label{4-mom}
\mathbb{E}[|\widehat{\mu}_\infty(k)|^4] \asymp    \left\{  \begin{array}{ll}    
k^{- 2 ( 1 -  \frac{\log \mathbb{E}[W^2]}{\log b})} & \text{if $0<\sigma^2< \frac{ \log b}{4}$}
\\
 k^{- 2 ( 1 -  \frac{\log \mathbb{E}[W^2]}{\log b})}  \cdot  \log k   & \text{if $\sigma^2 =\frac{\log b}{4}$}
\\
 k^{- (3 - \frac{\log \mathbb{E}[W^4]}{\log b})}  &   \text{if $\frac{\log b}{4}<\sigma^2< \frac{ \log b}{2}$}
\end{array}
\right. . 
\end{align}

To see this, we consider the  random weights in  the Biggins-Kyprianou's boundary case (the precise definitions are recalled in \S \ref{sec-BK-transformation}): 
\[
W= \frac{e^{-\beta \xi}}{\mathbb{E}[e^{-\beta \xi}]}  \text{\,\, with \,\,}
\mathbb{E}[\xi e^{-\xi}] = 0, \quad \mathbb{E}[e^{-\xi}] = \frac{1}{b} \text{\, and \,} 
\mathbb{P}(\xi\in (-\infty, 0))> 0.
\]  
Assume that $\mathbb{E}[e^{-t \xi}]<\infty$ for all $t> 0$. Then the expression \eqref{def-DF} for the Fourier dimension $D_F$ has a simpler form and exhibits a second order phase transition. Indeed, 
\[
D_F =D_F(\beta, \xi)=  \left\{
\begin{array}{lc}
\displaystyle \frac{2 \psi(\beta)-  \psi(2\beta) }{\log b} & \quad \text{if $0<\beta\le 1/2$}
\\
\displaystyle  \frac{2\psi(\beta)}{\log b} & \quad \text{if $1/2<\beta<1$}
\end{array}
\right. ,
\]
where $\psi$ is the strict convex function defined by 
$
\psi(t) = \psi_\xi(t)=\log \mathbb{E}[be^{-t\xi}]. 
$
See Lemma \ref{lem-psi} below for the basic properties of the function $\psi$.  In particular, we have $\psi(1)= \psi'(1)=0$ and $\psi''(1)>0$.  Therefore, for fixed $\xi$,  the map $\beta \mapsto D_F(\beta, \xi)$ exhibits a second order phase transition at $\beta = 1/2$.

A non-negative Borel measure $\nu$ on $\mathbb{R}$ is said to be  $\gamma$-upper Frostman regular if 
\begin{align}\label{def-FA}
\sup  \big\{    \frac{\nu(I)}{|I|^\gamma}:   \text{$I$ are finite  intervals of $\mathbb{R}$}  \big\} <\infty. 
\end{align}

Assume that $\mathbb{E}[W\log W]<\log b$ and $\mathbb{E}[W^t]<\infty$ for all $t>0$.   Then   almost surely on $\{\mu_\infty\ne 0\}$,  the measure $\mu_\infty$ satisfies the following Fourier restriction estimate: for any $1\le r< \frac{4}{4-D_F}$,  there exists $C(r, \mu_\infty)>0$ such that for all $f\in L^r(\mathbb{R})$, 
\begin{align}\label{F-R-ineq}
\| \widehat{f}\|_{L^2(\mu_\infty)} \le C(r, \mu_\infty) \| f\|_{L^r(\mathbb{R})}. 
\end{align}

