which is always finite for $0 < t \le 1$ (since $W$ is integrable with $\mathbb{E}[W]=1$).

\label{cor-HM-comp}
Assume that $\mathbb{X}$ is a  Banach space  having martingale type $p$ with $p \in (1,2]$ and let $\mathcal{V}: \mathfrak{B}^b([0,1])\rightarrow \mathbb{X}$ be a vector measure.  Assume that $\mathbb{E}[W^p]<\infty$.  If
\begin{align}\label{H-exp-exp}
 H_\mathcal{V}(p) +  \varphi_W(p) <   0, 
\end{align}
then the martingale $(Q_n \mathcal{V}([0,1]))_{n\ge 1}$ is $L^p$-uniformly bounded.

For any $1< p <2 \le q <\infty$ and  any vector measure $\mathcal{V}: \mathfrak{B}^b \rightarrow \ell^q$, we define a characteristic quantity
\begin{align}\label{chi-VWpq}
\chi(\mathcal{V}, W, p, q): =   \mathbb{E}\Big[ \Big\| \sum_{|u|\ge 1}    \Big(  \prod_{j=0}^{|u|-1} W(u|_j)^2 \Big)   \cdot  \big| \mathcal{V}(I_u)  \big|^2       \Big\|_{\ell^{q/2}}^{p/2} \Big].
\end{align}

\label{thm-precise}
Assume that $1<p<2\le q<\infty$.   Let  $\mathcal{V}: \mathfrak{B}^b\rightarrow \ell^q$ be a vector measure. Suppose that $\mathbb{E}[W^q]<\infty$.  Then
\begin{multline*}
\|\mathcal{V}([0,1])\|_{\ell^q}^p +    \|\mathring{W}\|_1^p\cdot    \chi(\mathcal{V}, W, p, q)   
\\
\lesssim_{p,q}\sup_{n\ge 1} \mathbb{E} \Big[ \big  \| Q_n\mathcal{V}([0,1])\big\|_{\ell^q}^p \Big]  \lesssim_{p,q} 
\\
