\label{lem-I}
Given any integer $N\ge 1$. For any $u\in \mathcal{A}^*$ with $1\le |u|\le N$, we have 
\[
\mathbb{E}_{u^{-}}\Big[\big|D_u \big[ M_N^\mathcal{V}\big]\big|^2\Big] =\mathrm{Var}(W)  \cdot \Big(  \prod_{j=0}^{|u|-1} W(u|_j)^2 \Big)   \cdot  \big| \mathcal{V}(I_u)  \big|^2. 
\]
In particular, $\mathbb{E}_{u^{-}}\big[\big|D_u \big[ M_N^\mathcal{V}\big]\big|^2\big]$ does not depend on $N$ provided that $1\le |u|\le N$. Hence  
\begin{align*}
 T_1 (N)=    \mathrm{Var}(W)^{p/2} 
 \cdot  \mathbb{E}\Big[ \Big\| \sum_{1\le |u|\le N}    \Big(  \prod_{j=0}^{|u|-1} W(u|_j)^2 \Big)   \cdot  \big| \mathcal{V}(I_u)  \big|^2       \Big\|_{\ell^{q/2}}^{p/2} \Big]. 
\end{align*}

\label{lem-II-le-I}
Assume that $
\mathbb{E}[W^q]<\infty$. Then 
\begin{align*}
T_2(N) \le   \|\mathring{W}\|_q^p   
 \cdot   \mathbb{E}\Big[ \Big\| \sum_{1\le |u|\le N}    \Big(  \prod_{j=0}^{|u|-1} W(u|_j)^2 \Big)   \cdot  \big| \mathcal{V}(I_u)  \big|^2       \Big\|_{\ell^{q/2}}^{p/2} \Big].
\end{align*}

Since $q\ge 2$,  by the   inequality $(a+b)^t \ge a^t + b^t$ for  any $a, b \ge 0$ and $t \ge 1$, we get 
\begin{align*}
\Big\| \sum_{i} |f_i|^2 \Big\|_{\ell^{q/2}}^{q/2}   = \sum_{s\in \mathbb{N}} \Big(\sum_{i}  |f_i(s) |^2\Big)^{q/2} \ge \sum_{s\in \mathbb{N}} \sum_{i}  |f_i(s) |^q  =  \sum_{i}   \sum_{s\in \mathbb{N}} |f_i(s) |^q   =  \sum_i \| f_i\|_{\ell^q}^q. 
\end{align*} 
This is the desired inequality.

\label{lem-abs}
Let $(\Sigma,  \mathcal{B},  \rho)$  be  a measure space equipped  with a non-negative $\sigma$-finite measure  $\rho$. 
 Consider any $p_1\ge 1$, then for any $0<p_2<\infty$ and  any finite sequence  of vector-valued functions $(g_i)_{i}$ in $L^{p_2}(\Sigma, \rho; \ell^{p_1})$, 
 \begin{align}\label{KK-abs}
\big \| \sum_i \epsilon_i g_i\big\|_{L^{p_2}(\Delta\times \Sigma; \, \ell^{p_1})} \asymp_{p_1, p_2}  \big \| \sum_i \epsilon_i |g_i|\big\|_{L^{p_2}(\Delta\times \Sigma; \, \ell^{p_1})},
 \end{align}
 where  $\Delta\times \Sigma$ is equipped with the measure $d\epsilon \otimes d\rho$.

