Define 
\[
S_0 : = \Big\{  (\alpha, p,q) \Big|  0< \alpha < \kappa, q>\frac{1}{\kappa-\alpha} \text{\, and \,} p> \frac{q\kappa}{q(\kappa- \alpha) -1} \Big\}.
\]
We want to show that for all tuple $(\alpha, p, q)\in S_0$, 
\begin{align}\label{goal-HV}
H_\mathcal{V}(p)  \le     p-1 -  (\tau - 1) \underline{\dim}_{\tau}(\nu) \, \,
\text{with $\tau = \tau(\alpha, p, q) = p\frac{ q (\kappa - \alpha)  -1}{q \kappa}>1$.}
\end{align}


For any $\varepsilon\in (0, \kappa)$, define $\kappa_\varepsilon= \kappa- \varepsilon$ and set 
\[
S_\varepsilon: = \Big\{  (\alpha, p,q) \Big|  0< \alpha < \kappa_\varepsilon, q>\frac{1}{\kappa_\varepsilon-\alpha} \text{\, and \,} p> \frac{q\kappa_\varepsilon}{q(\kappa_\varepsilon- \alpha) -1} \Big\}.
\]
It can be directly shown that if $\kappa> \varepsilon_1 >\varepsilon_2>0$, then 
\begin{align}\label{S-monotone}
S_{\varepsilon_1} \subset S_{\varepsilon_2} \text{\, and \,} 
\bigcup_{0< \varepsilon< \kappa} S_\varepsilon = S_0.
\end{align}


Now fix any tuple $(\alpha, p, q)\in S_0$.  By the monotonicity \eqref{S-monotone},  there exists $\varepsilon_0\in (0, \kappa)$ such that for all $0< \varepsilon<\varepsilon_0<\kappa$,  this fixed tuple $(\alpha, p, q)$ belongs to $S_\varepsilon$.   Therefore, by  the continuity of  the function $\tau\mapsto (\tau-1)\underline{\dim}_\tau(\nu)$ on $(1, \infty)$, to prove the inequality \eqref{goal-HV} for this tuple $(\alpha, p, q)$, it suffices to prove that,   for any $\varepsilon \in (0, \varepsilon_0)$, 
\begin{align}\label{goal-HV-bis}
H_\mathcal{V}(p)  \le     p-1 -  (\tau_\varepsilon - 1) \underline{\dim}_{\tau_\varepsilon}(\nu) \, \,
\text{with $\tau_\varepsilon = p\frac{ q (\kappa_\varepsilon - \alpha)  -1}{q \kappa_\varepsilon}>1$.}
\end{align}


So we  take any  $\varepsilon\in (0, \varepsilon_0)$. For simplifying notation, from now on, we  write 
\[
 \kappa' = \kappa_\varepsilon= \kappa - \varepsilon>0 \text{\, and \,} \tau'= \tau_\varepsilon = p\frac{ q (\kappa' - \alpha)  -1}{q \kappa'}> 1. 
\] 
By Proposition~\ref{lem-Fdecay},   we may  assume  that there exists  $c>0$ such that 
\begin{align*}
\sup_{u\in \mathcal{A}^*} \Big|\int_{I_u}e^{-i 2\pi st}\nu(dt)\Big| \le \frac{c}{s^{\kappa'}} \quad \text{for all $s>1$}. 
\end{align*}
In particular,  for any $u\in \mathcal{A}^*$,  take $C = \max\{c, 1\}$, we have 
\begin{align}\label{b-adic-ass}
\Big|\int_{I_u}e^{-i 2\pi st}\nu(dt)\Big| \le  C \min\big\{ s^{-\kappa'},\, \nu(I_u) \big\}.
\end{align}
Recall the definition \eqref{def-H-mart} of $T_n^\mathcal{V}$ and \eqref{def-rsigma} of $H_\mathcal{V}(p)$.  Here we have 
\begin{align*}
 T_n^{\mathcal{V}} =   b^n \sum_{|u|=n}      \Big(    s^\alpha \int_{I_u}  e^{-i 2 \pi s t}\nu(dt)\Big)_{s \ge 1}  \mathds{1}_{I_u}.
\end{align*}
Therefore,  by \eqref{b-adic-ass}, 
\begin{align*}
\|T_n^{\mathcal{V}}\|_{L^p(\ell^q)}^p & \le  b^{n(p-1)}  C^p  \sum_{|u|=n}     \Big( \sum_{s=1}^\infty   s^{\alpha q}    \min\big\{ s^{-\kappa' q},\, \nu(I_u)^q \big\} \Big)^{p/q}. 
\end{align*}
Then, by using the following decomposition 
\begin{align*}
\sum_{s=1}^\infty   =\sum_{1\le s\le a(u)-1}  + \sum_{ a(u)-1<s<a(u)+1} + \sum_{s\ge a(u)+1}\quad \text{with $a(u)= \nu(I_u)^{-1/\kappa'}$}
\end{align*}
and the elementary inequality $(x+y +z)^t\le  3^t (x^t + y^t +z^t)$ for all $x, y, z, t \ge 0$, we obtain 
\begin{align*}
\|T_n^{\mathcal{V}}\|_{L^p(\ell^q)}^p & \le  b^{n(p-1)}  C^p  3^{p/q}  \sum_{|u|=n}     \Big[ \Big(   \sum_{1\le s\le a(u) }    s^{\alpha q}    \cdot  \nu(I_u)^q  \Big)^{p/q} +   \Big(\sum_{s> a(u)}    s^{-(\kappa'-\alpha)q}\Big)^{p/q} 
\\
& \qquad\qquad  \qquad \qquad   + \Big(\sum_{ a(u)-1<s<a(u)+1}  s^{\alpha q}    \min\big\{ s^{-\kappa' q},\, \nu(I_u)^q \big\} \Big)^{p/q}\Big]. 
\end{align*}
Since 
\begin{align*}
\sum_{1\le s\le a(u) -1 }    s^{\alpha q} \cdot  \nu(I_u)^q  \le  \nu(I_u)^q  \cdot \int_1^{a(u)}  t^{\alpha q} dt  \le \nu(I_u)^{q-\frac{\alpha q +1}{\kappa'}}
\end{align*}
and 
\begin{align*}
\sum_{s\ge  a(u)+1}    s^{-(\kappa'-\alpha)q} \le \int_{a(u)}^\infty \frac{dt}{t^{(\kappa' - \alpha) q}} \le  \frac{1}{(\kappa' - \alpha) q -1}  \nu(I_u)^{q-\frac{\alpha q +1}{\kappa}}
\end{align*}
and  (by assumption $\alpha <\kappa'$ and $\nu(I_u)\le 1$)
\begin{align*}
\sum_{ a(u)-1<s<a(u)+1}  s^{\alpha q}    \min\big\{ s^{-\kappa' q},\, \nu(I_u)^q \big\}  &  \le   a(u)^{\alpha q} \nu(I_u)^q + a(u)^{(\alpha-\kappa')q}  
\\
&  =  2\nu(I_u)^{q- \frac{\alpha q}{\kappa'}} \le  2\nu(I_u)^{q- \frac{\alpha q +1}{\kappa'}},
\end{align*}
there exists a constant $c(\kappa', \alpha, p, q)>0$ such that 
\begin{align*}
\|T_n^{\mathcal{V}}\|_{L^p(\ell^q)}^p & \le  c(\kappa', \alpha, p, q)   \cdot  b^{n(p-1)}  \sum_{|u|=n}  \nu(I_u)^{p \frac{ q(\kappa'-\alpha) -1}{q \kappa'}}
\\ 
& =  c(\kappa', \alpha, p, q)   \cdot  b^{n(p-1)}  \sum_{|u|=n}  \nu(I_u)^{\tau'}. 
\end{align*}
By Lemma \ref{lem-lq-dim}, for any small enough $\delta>0$, there exists $n(\delta, \tau') \in \mathbb{N}$ such that 
\[
 \sum_{|u|=n}  \nu(I_u)^{\tau'}   \le  b^{-n (\tau'-1) (\underline{\dim}_{\tau'}(\nu) - \delta)}  \,\,  \text{for all $n\ge n(\delta, \tau')$.}
\]
Therefore, for all $n\ge n(\delta, \tau')$,
\begin{align*}
\|T_n^{\mathcal{V}}\|_{L^p(\ell^q)}^p & \le  c(\kappa', \alpha, p, q)   \cdot  b^{n(p-1)}  \sum_{|u|=n}  \nu(I_u)^{\tau'}
\\
&\le   c(\kappa', \alpha, p, q)   \cdot  b^{n(p-1)} \cdot  b^{-n (\tau'-1) (\underline{\dim}_{\tau'}(\nu) - \delta)}. 
\end{align*}
It follows that 
\[
H_\mathcal{V}(p) = \limsup_{n\to\infty}  \frac{ \log \|T_n^{\mathcal{V}}\|_{L^p(\ell^q)}^p }{n\log b}   \le     p-1 - (\tau'-1) ( \underline{\dim}_{\tau'}(\nu) - \delta). 
\]
By letting $\delta \to 0^{+}$, we obtain  the desired inequality \eqref{goal-HV-bis} and  end the  whole proof.

