\label{Prop-c-clt}
Suppose that $(\Omega,\mathcal{F}, (\mathcal{F}_n)_{n\in\mathbb{N}};\mathbb{P})$ is  a filtered probability space. For any fixed   $n\in \mathbb{N}$, there are two  sequences of random variables   $\{X_{n,k}: 1\leq k \leq t_n\}$  and  $\{Y_{n,k}: 1\leq k \leq t_n\}$ satisfying the following conditions:
\begin{itemize}
\item[(1)] $\lim_{n\rightarrow\infty} t_n=\infty$;
\item[(2)]  The family of real-valued random variables $\{X_{n,k}: 1\leq k\leq t_n\}$ are $\mathcal{F}_n$-measurable;
\item[(3)] The family of complex-valued random variables $\{Y_{n,k}: 1\leq k\leq t_n\}$ are independent of  $\mathcal{F}_n$; 
\item[(4)]  $\{Y_{n,k}: 1\leq k\leq t_n\}$ are i.i.d. copies of a complex random variable $Y$ with 
\[
\mathbb{E}[Y]=0,\quad \mathbb{E}[Y^2]=0,\quad \text{and}\quad \mathbb{E}[|Y|^2]=c\in (0,\infty);
\] 



\item[(5)]
\[
\mathbb{E}\Big[\Big|\sum_{k=1}^{t_n} X_{n,k}Y_{n,k}\Big|^2\Big]=c>0
\]
\item[(6)] There exists a  sequence of non-negative random variables $(M_n)_{n\in\mathbb{N}}$ such that 
\begin{align}\label{eqn-convergence}
\mathbb{E}\Big[\Big|\sum_{i=1}^{t_n} X_{n,k}Y_{n,k}\Big|^2\big|\mathcal{F}_n\Big]=c\sum_{i=1}^{t_n} X_{n,k}^2=cM_n
\end{align}
and
\[
\mathbb{E}\Big[\Big(\sum_{i=1}^{t_n} X_{n,k}Y_{n,k}\Big)^2\big| \mathcal{F}_n\Big]=0.
\]
In other words, $\mathbb{E}[M_n]=1$.
\item[(7)] $\lim_{n\rightarrow \infty}M_n=M_\infty$ almost surely (in probability), where $M_\infty\in \mathcal{F}_\infty$.
\item[(8)] For any $\varepsilon>0$, 
\begin{align}\label{eqn-hjhi}
\lim_{n\rightarrow\infty} \mathbb{E}\Big[\sum_{k=1}^{t_n} |X_{n,k}|^2|Y_{n,k}|^2\mathds{1}(|X_{n,k}Y_{n,k}|>\varepsilon) \big|  \mathcal{F}_n\Big]=0 \quad  \text{a.s. (in probability)}
\end{align}
\end{itemize}
Then for any bounded continuous function $\phi$,
\[
\lim_{n\rightarrow\infty}\mathbb{E}\Big[\phi\Big(\sum_{k=1}^{t_n} X_{n,k}Y_{n,k}\Big) \big|\mathcal{F}_n\Big]=\mathbb{E}\left[\phi(\mathcal{N}_{\mathbb{C}}(0, M_{\infty}))| \mathcal{F}_\infty\right]\quad \text{a.s. (in probability)}
\]
where $\mathcal{N}_{\mathbb{C}}(0, M_{\infty})$ is a complex normal random variable with mean zero and covariance matrix given by 
\[
M_\infty\begin{pmatrix}
1/2&0\\
0&1/2\\
\end{pmatrix}.
\]

